```go
package cart

// Item represents a product in the cart
type Item struct {
	ID       string
	Name     string
	Price    float64
	Quantity int
}

// ShoppingCart holds items for purchase
type ShoppingCart struct {
	items map[string]*Item
}

// New creates a new shopping cart
func New() *ShoppingCart {
	return &ShoppingCart{
		items: make(map[string]*Item),
	}
}

// AddItem adds an item to the cart or increases quantity if it exists
func (c *ShoppingCart) AddItem(id, name string, price float64, quantity int) {
	if existing, ok := c.items[id]; ok {
		existing.Quantity += quantity
	} else {
		c.items[id] = &Item{
			ID:       id,
			Name:     name,
			Price:    price,
			Quantity: quantity,
		}
	}
}

// RemoveItem removes an item entirely from the cart
func (c *ShoppingCart) RemoveItem(id string) {
	delete(c.items, id)
}

// UpdateQuantity changes the quantity of an existing item
func (c *ShoppingCart) UpdateQuantity(id string, quantity int) {
	if item, ok := c.items[id]; ok {
		if quantity <= 0 {
			delete(c.items, id)
		} else {
			item.Quantity = quantity
		}
	}
}

// GetItem retrieves an item by ID
func (c *ShoppingCart) GetItem(id string) (*Item, bool) {
	item, ok := c.items[id]
	return item, ok
}

// GetItems returns all items in the cart
func (c *ShoppingCart) GetItems() []*Item {
	result := make([]*Item, 0, len(c.items))
	for _, item := range c.items {
		result = append(result, item)
	}
	return result
}

// Total calculates the total price of all items
func (c *ShoppingCart) Total() float64 {
	var total float64
	for _, item := range c.items {
		total += item.Price * float64(item.Quantity)
	}
	return total
}

// ItemCount returns the total number of items (sum of quantities)
func (c *ShoppingCart) ItemCount() int {
	var count int
	for _, item := range c.items {
		count += item.Quantity
	}
	return count
}

// Clear empties the cart
func (c *ShoppingCart) Clear() {
	c.items = make(map[string]*Item)
}

// IsEmpty returns true if the cart has no items
func (c *ShoppingCart) IsEmpty() bool {
	return len(c.items) == 0
}
